Method.Implementation:
#dim tSC As %Status = $$$OK
 NEW $NAMESPACE
 try {
 	set $NAMESPACE = nmSp
 } catch err
 {
	 return "Invalid namespace: " _ nmSp _ err.Name _ " " _ err.Code

 }
 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "NAMESPACE: " _ $NAMESPACE)
 set tItemName = $ZSTRIP(tItemName,"*W") 
 try
 {
  set ..DeployDirectory = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK
 } catch err
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Error: " _ err.Name _ " " _ err.Data _ " " _ ..DeployDirectory)
 }


 set tProductionName = ##class(Ens.Director).GetActiveProductionName()

 if tProductionName = ""
 {
  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Could not get active production in " _ $NAMESPACE)
  return "Active production not found in " _ $NAMESPACE
 }
 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Active PROD: " _ tProductionName)


 set env = "Dev"

 if $$$ISERR( ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).DoSvnSetup(userNm, passwd))
 {
	 return "ERROR in SVN"
 }

 Set tExportFilename = ..DeployDirectory_"Deployment_CONFIG_" _tItemName_".xml"

 Do ..CreateComment(tItemName)

 set tSC = ..CreateConfigFile(tItemName, tExportFilename, tProductionName)
 if $$$ISERR(tSC)
 {
	 Set comment =  ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, "Config file create failed. ")
	 return comment
 }
 else
 {
 	Set tExportClsFilename = ..DeployDirectory_"Deployment_CLS_"_tItemName_".xml"
 	set tSC = ..CreateClassFile(tItemName,  tExportClsFilename, nmSp, tProductionName, userNm, passwd, .exclFiles) 
 }
 if $$$ISERR(tSC)
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Class file was not created. ")
	 if tSC [ "No Classes to expo"
	 {
		 set tExportClsFilename = ""
	 }
	 else
	 {
		Set comment = ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, "Class file create failed. ")
	 	return comment
	 }
 }
 Do ..tComments.Rewind()
 set len = 32656
 #dim sc as %Status
 set comment = ..tComments.Read(.len, .sc)
 set commitComment = ""
 if $$$ISOK(sc)
 {
 	set tSC = ..CheckinFiles(tExportFilename _ " " _ tExportClsFilename, userNm, passwd, comment, .commitComment)
 }
 else
 {
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Error in reading comments" )
 }
 if $$$ISERR(tSC)
 {
	 Set comment =  ##class(IHC.ITF.ITFCOMMON.Utility).getErrorMsg(tSC, "Could not create files. ")
 }
 set retStr = commitComment _ comment

  Set tItem = $O(exclFiles(""))
  if (tItem '= ""){
	 Set retStr = retStr _ "<BR><BR><B><I>WARNING. Following files are excluded from class deployment file: </I></B><BR>"
  }
		While (tItem '= ""){
			Set retStr = retStr _ tItem _ "<BR>"
			Set tItem = $O(exclFiles(tItem))
		}
  set retStr = $REPLACE(retStr, "ItemName:", "<BR>ItemName:")
 return tItemName _ ": " _ retStr



 Do ..tComments.Rewind()

 Set:(tItemName '[ "||") tItemName = tProductionName_"||"_tItemName

	Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(tItemName)
	If ' $IsObject(tItem)
	{
		Quit $$$ERROR($$$EnsErrGeneral, "Can't open object: " _tItemName )
	}

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( tItemName _" is valid in " _ tProductionName)
	Set tSC=##class(%Studio.Project).Delete(..tProjectName) 
	Set tSC = ##class(Ens.Deployment.Utils).CreatePTDFromItem(.tItem,.tPTDName)	
	If tPTDName '= "" 
	{
		     //Create Deployment file with PTDs	
		     // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( 	tPTDName  )    	
		   Set tContentsList(tPTDName_".PTD")=""

		   Set tSC =##class(Ens.Deployment.Utils).CreateExportPackageFromProjectList(..tProjectName,.tContentsList,tExportFilename,tProductionName,..tComments,..tProductionClassIncluded)
		   if $$$ISERR(tSC)
		   {
			   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Failed to Export: " _ tSC)
			   SET tSC =  $$$ERROR($$$EnsErrGeneral, "Failed to create ExportPackage file")
		   }
		   else
		   {
		   		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Created export file: " _ tExportFilename _ "stat: " _ tSC)
		   }
		   Do ##class(Ens.Util.ProjectTextDocument).Delete(tPTDName_".PTD")

	}
	else
	{
		SET tSC =  $$$ERROR($$$EnsErrGeneral, "Failed to create PTDFromItem")
	}
	Quit tSC


 Do ..tComments.MoveToEnd()

 Set:(tItemName '[ "||") tItemName = tProductionName_"||"_tItemName

 Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(tItemName)
 If ' $IsObject(tItem)
 {
	Quit $$$ERROR($$$EnsErrGeneral, "Can't open object: " _tItemName )
 }

 // Open production and get items for the component
 Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tSC)
 Set tSC=tProduction.getProjectArrayFromConfigItem(tItem,.tProjectArray) 
   // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "getProjectArrayFromConfigItem: " _ tSC)
 Quit:$$$ISERR(tSC) tSC

 Set tSC=tProduction.expandProjectArray(.tProjectArray)  Quit:$$$ISERR(tSC) tSC
 // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "expandProjectArray " _ tSC)
 Quit:$$$ISERR(tSC) tSC

 set tSC = tProduction.createStudioProjectFromArray(.tProject,.tProjectArray, ..tProjectName, "DESC")
  // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "createStudioProjectFromArray " _ tSC)
 set num =1
 Set k=""  
 set excludefileList = ""
 For 
  { 
	   #dim tItem As %Studio.ProjectItem 
		Set tItem=tProject.Items.GetNext(.k)  Quit:""=k||'$IsObject(tItem)
		Set tItemName=tItem.Name

		if '(tItemName [ "ITFCOMMON")
		{


			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( userNm _ " : " _ num _". " _ tItemName _ " = " _  tItem.Type)

			// Does the Name end with type
			if $F(tItemName, tItem.Type) >  $L(tItemName)
			{
				set item = tItemName
	 		}
	 		else
	 		{
				set item = tItemName _ "." _ tItem.Type
	 		}

	 		if (item [ "CLS")
	 		{

	 			set tSC = ..CheckItemWithSrcCtrl(item,  userNm, passwd, nmSp, .excludefileList)
	 			if (tSC = 999)
	 			{
		 			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( userNm _ ", Excluded file: " _ item)
	 			}
	 			elseif ($$$ISOK(tSC))
	 			{
	 				Set tFullList(item)=""

	   				set num = num + 1
	 			}	 			

	 			elseif $$$ISERR(tSC)
	 			{
		 			Return tSC 
	 			}

	 		}
	 		elseif( item [ "HL7")
	 		{
		 		SET excludefileList(item_": Deploy this HL7 schema before deploying this component") = ""
	 			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( userNm _ ", Excluded file: " _ item)
	 		}	
	 		else
	 		{

	  			Set tFullList(item)=""

	   			set num = num + 1
	 		}
		}
	}
	if (num > 1)
	{
       Do ..tComments.Rewind()

       	Set tSC =##class(Ens.Deployment.Utils).CreateExportPackageFromProjectList(..tProjectName,.tFullList,tExportClsFilename,tProductionName,..tComments,..tProductionClassIncluded)
       	if $$$ISERR(tSC)
   		{
	   		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Failed to Export: " _ tSC)
	   		QUIT tSC
   		}


	}
	else
	{
		set tSC = $$$ERROR($$$EnsErrGeneral, "No Classes to export")
		Quit tSC
	}

	if ##class(%File).Exists(tExportClsFilename)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Created Class file: " _ tExportClsFilename)
	}
	else
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "CLASS file NOT EXPORTED")
	}


	Quit tSC

#dim tSC As %Status
set tSC = $$$OK

if ##class(%RoutineMgr).Exists(itemNm)
{

	set extNm = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExternalName(itemNm, userNm)
	if ##class(%File).Exists(extNm)
	{
	       // found file, get time and SVN information
		   set fileModTm = ##class(%File).GetFileDateModified(extNm)
		   //Get internal time	
		   set intTime= $ZDATETIMEH(##class(%RoutineMgr).TS(itemNm), 3, 1)
		   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("TIME: " _ itemNm _ ": " _ intTime _ ", file: " _ extNm _ " " _ fileModTm)

		   set ddIntTime = $P(intTime, ",", 1)
		   set ddFileModTm = $P(fileModTm, ",", 1)
		   set tmIntTime = $P(intTime, ",", 2)
		   set tmFileModTm = $P(fileModTm, ",", 2)
		   if ( ((ddIntTime) > (ddFileModTm)) || (((ddIntTime) = (ddFileModTm)) &&  (tmIntTime > tmFileModTm)) )
		   {
			   set diffStr = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetDiff(nmSp, userNm, extNm)
			   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Complie time is greater than svn time, Diff file: " _ diffStr)
			   if ( $F(diffStr, "identical") > 0)
			   {
				   set tSC = ..getCommentForFile(itemNm, extNm, userNm, passwd)
			   }
			   elseif ( itemNm [ "HL7")
			   {
				   Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( " !!! Internal time is later than Checkin time for HL7 file")
			   		Set pExcList(extNm)=""
	   				set tSC = 999
		   	   }
			   else
			   {
			   	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( " !!! Internal time is later than Checkin time")
			  	set tSC = $$$ERROR($$$EnsErrGeneral, "Internal time is later than Checkin time : " _ itemNm)
			   }
		   }
		   else
		   {
		   	set tSC = ..getCommentForFile(itemNm, extNm, userNm, passwd)
		   } 		
	  }
	  else
	  {
	   		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( " !!! File not in source control: " _ extNm)
	   		if ( $F(extNm, "Transform/Dtl") > 0 || $F(extNm,"Process/Bpl") )
	   		{
	   		  set tSC = $$$ERROR($$$EnsErrGeneral, "Source File not in source control: " _ extNm)
	   		  Return tSC
	   		}
	   		Set pExcList(extNm)=""
	   		set tSC = 999
	  }
}
Quit tSC

	set fileInfo = ""
	Set fileNm = ""
 	if $$$ISERR( ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).DoSvnSetup(usrNm, passwd))
 	{
	 	return "ERROR in SVN"
 	}
	  set ..DeployDirectory = $$$USRRELEASEBASEDIR _ usrNm _ $$$SVNSRCTRUNK

	if (config = 1)
	{
	 Set fileNm = ..DeployDirectory_"Deployment_CONFIG_" _tItemName_".xml"
	}
	else
	{
		Set fileNm = ..DeployDirectory_"Deployment_CLS_" _tItemName_".xml"
	}
    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm, "GetVersions: " _ fileNm _", Name: " _ tItemName _ "$")

	Do ##class(%File).Delete(fileNm)
	Set cmd= $$$SVNUPDATE _ " --username " _ usrNm _ " --password '" _ passwd _ "' " _  fileNm 

	Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	if (status '= 0)
	{
		set fileInfo = $$$SVNUPDATE _ " failed for: " _ fileNm
	}
	if ##class(%File).Exists(fileNm)
	{
			set tempFile = 	fileNm _ "Temp"
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Checked out " _ fileNm)
			Set cmd= $$$SVNINFO _ fileNm _ " >> " _ tempFile

			Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	        Set cmd=  $$$SVNLOG _" --username " _ usrNm _ " --password '" _ passwd _ "' " _ fileNm _ " >> " _ tempFile 

			Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	  		if (##class(%File).Exists(tempFile) )
	  		{
         		// Call the function to get svn information
         		Set fileInfo = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetFileContent(tempFile)       
	  		}
	  		else
	  		{
		  		SET fileInfo = "svn command failed: " _ $$$SVNLOG
	  		}
	}
	else {
  			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(usrNm,   "Could not find file " _ fileNm)

  			if (config = 1)
  			{
	  			set fileInfo = "Could not find file " _ fileNm
  			}
  			else
  			{
	  			// CLASS file not found
	  			set fileInfo = ""
  			}
 	}

	Quit fileInfo
